document.addEventListener("DOMContentLoaded",()=>{const e=[{label:"Introduced",value:"2016"},{label:"Service Type",value:"Semi-High-Speed"},{label:"Top Speed",value:"160 km/h"},{label:"Coach Type",value:"LHB Chair Car"}],n=document.getElementById("quick-facts-container");n&&e.forEach(e=>{const t=document.createElement("div");t.className="fact-card",t.innerHTML=`\n                <div class="fact-label">${e.label}</div>\n                <div class="fact-value">${e.value}</div>\n            `,n.appendChild(t)});const t=[{year:"2016",title:"Inaugural Run",description:"Gatimaan Express was flagged off on April 5, 2016, operating between Hazrat Nizamuddin (Delhi) and Agra Cantonment."},{year:"2018",title:"Extension to Gwalior",description:"In February 2018, the service was extended up to Gwalior."},{year:"2018",title:"Extension to Jhansi",description:"Shortly after, in April 2018, the route was further extended to Virangana Lakshmibai (Jhansi), providing better connectivity."}],i=document.getElementById("timeline-container");i&&t.forEach(e=>{const n=document.createElement("div");n.className="timeline-item",n.tabIndex=0,n.innerHTML=`\n                <div class="timeline-year">${e.year}</div>\n                <div class="timeline-content">\n                    <h3>${e.title}</h3>\n                    <p>${e.description}</p>\n                </div>\n            `,i.appendChild(n)});const a=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{threshold:.1});document.querySelectorAll(".timeline-item").forEach(e=>a.observe(e));const s=document.getElementById("route-container");s&&(s.innerHTML='\n            <div class="route-node">\n                <span class="node-label">Origin</span>\n                <h3 class="node-city">Delhi (NZM)</h3>\n            </div>\n            <div class="route-connector" aria-hidden="true">\n                <span>Agra Cantt</span>\n                <span class="dot"></span>\n                <span>Gwalior</span>\n            </div>\n            <div class="route-node">\n                <span class="node-label">Destination</span>\n                <h3 class="node-city">Jhansi (VGLJ)</h3>\n            </div>\n        ');const r=[{title:"High-Speed Operation",description:"Designed for a maximum operational speed of 160 km/h between Delhi and Agra, facilitated by a powerful WAP-5 locomotive."},{title:"Modern LHB Coaches",description:"Equipped with Linke Hofmann Busch (LHB) coaches known for their anti-telescopic safety features."},{title:"Bio-Toilets",description:"Features zero-discharge bio-toilets for improved hygiene and environmental compliance."}],o=document.getElementById("features-container");o&&r.forEach(e=>{const n=document.createElement("div");n.className="feature-card",n.tabIndex=0,n.innerHTML=`\n                <h3>${e.title}</h3>\n                <p>${e.description}</p>\n            `,o.appendChild(n)});const c=[{icon:"🪑",title:"Executive & AC Chair Car",description:"Offers spacious Executive Class and standard AC Chair Car seating for a comfortable day journey."},{icon:"🍽️",title:"Premium Catering",description:"Passengers are served high-quality meals, often with choices of Indian and Continental cuisine."},{icon:"📢",title:"Passenger Info System",description:"Features GPS-based passenger information systems and sliding doors in coaches."},{icon:"🛡️",title:"Train Hostesses",description:"It introduced airline-style train hostesses/stewards for passenger assistance."}],d=document.getElementById("facilities-container");d&&c.forEach(e=>{const n=document.createElement("div");n.className="facility-card",n.tabIndex=0,n.innerHTML=`\n                <div class="facility-icon" aria-hidden="true">${e.icon}</div>\n                <h3>${e.title}</h3>\n                <p>${e.description}</p>\n            `,d.appendChild(n)});const l=["Gatimaan Express covers the 188 km distance between Delhi and Agra in just about 100 minutes.","It was the first train in India to feature train hostesses, similar to airlines.","To achieve 160 km/h, the tracks on the Delhi-Agra route were specially upgraded with robust fencing and improved signaling."],p=document.getElementById("trivia-container");p&&l.forEach(e=>{const n=document.createElement("div");n.className="trivia-card",n.tabIndex=0,n.innerHTML=`<p>${e}</p>`,p.appendChild(n)})});